class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n + 1];
        dp[0] = 0;
        dp[1] = nums[0];
        for (int i = 2; i <= n; i++) {
            int skip = dp[i - 1];
            int take = dp[i - 2] + nums[i - 1];
            dp[i] = Math.max(skip, take);
        }
        return dp[n];
    }
}

class Solution {
    public int rob(int[] nums) {
        int twoHousesBack = 0;
        int oneHouseBack = 0;
        for (int money : nums) {
            int current = Math.max(oneHouseBack, twoHousesBack + money);
            twoHousesBack = oneHouseBack;
            oneHouseBack = current;
        }
        return oneHouseBack;
    }
}

import java.util.Arrays;

class Solution {
    public int rob(int[] nums) {
        int[] memo = new int[nums.length];
        Arrays.fill(memo, -1);
        return bestFrom(nums, 0, memo);
    }

    private int bestFrom(int[] nums, int index, int[] memo) {
        if (index >= nums.length) {
            return 0;
        }
        if (memo[index] != -1) {
            return memo[index];
        }
        int skip = bestFrom(nums, index + 1, memo);
        int take = nums[index] + bestFrom(nums, index + 2, memo);
        memo[index] = Math.max(skip, take);
        return memo[index];
    }
}

class Solution {
    public int rob(int[] nums) {
        int robbed = Integer.MIN_VALUE / 4;
        int skipped = 0;
        for (int money : nums) {
            int nextRobbed = skipped + money;
            int nextSkipped = Math.max(skipped, robbed);
            robbed = nextRobbed;
            skipped = nextSkipped;
        }
        return Math.max(robbed, skipped);
    }
}

class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        if (n == 1) {
            return nums[0];
        }
        nums[1] = Math.max(nums[0], nums[1]);
        for (int i = 2; i < n; i++) {
            nums[i] = Math.max(nums[i - 1], nums[i] + nums[i - 2]);
        }
        return nums[n - 1];
    }
}
